**Directives** provide a way to conditionally include or exclude fields based on variables, allowing dynamic query structure.

```graphql
# Built-in directives
query GetUser($userId: ID!, $includeEmail: Boolean!, $skipPosts: Boolean!) {
  user(id: $userId) {
    id
    name
    email @include(if: $includeEmail)
    posts @skip(if: $skipPosts) {
      id
      title
    }
  }
}

# Variables
{
  "userId": "123",
  "includeEmail": true,
  "skipPosts": false
}

# Custom directives
directive @auth(requires: Role = USER) on FIELD_DEFINITION
directive @deprecated(reason: String = "No longer supported") on FIELD_DEFINITION
directive @rateLimit(max: Int!, window: String!) on FIELD_DEFINITION

# Schema with custom directives
type Query {
  users: [User!]! @auth(requires: ADMIN)
  posts: [Post!]!
  oldField: String @deprecated(reason: "Use newField instead")
  search(query: String!): [Result!]! @rateLimit(max: 10, window: "1m")
}
```

```javascript
// Custom directive implementation
const { SchemaDirectiveVisitor } = require('apollo-server');

class AuthDirective extends SchemaDirectiveVisitor {
  visitFieldDefinition(field) {
    const { resolve = defaultFieldResolver } = field;
    const requiredRole = this.args.requires;

    field.resolve = async function(...args) {
      const [, , context] = args;

      if (!context.user) {
        throw new Error('Authentication required');
      }

      if (context.user.role !== requiredRole) {
        throw new Error('Insufficient permissions');
      }

      return resolve.apply(this, args);
    };
  }
}

// Register directive
const server = new ApolloServer({
  typeDefs,
  resolvers,
  schemaDirectives: {
    auth: AuthDirective
  }
});
```

GraphQL provides **type-level validation** automatically, but **business logic validation** must be implemented in resolvers.

```graphql
# Type-level validation (automatic)
input CreateUserInput {
  name: String!        # Required string
  email: String!       # Required string
  age: Int            # Optional integer
  role: UserRole!     # Required enum
}

enum UserRole {
  USER
  ADMIN
  MODERATOR
}

type Mutation {
  createUser(input: CreateUserInput!): User!
}
```

```javascript
// Business logic validation in resolvers
const { UserInputError } = require('apollo-server');
const validator = require('validator');

const resolvers = {
  Mutation: {
    createUser: async (parent, { input }, context) => {
      // Validate email format
      if (!validator.isEmail(input.email)) {
        throw new UserInputError('Invalid email format', {
          invalidArgs: ['email']
        });
      }

      // Validate age range
      if (input.age && (input.age < 13 || input.age > 120)) {
        throw new UserInputError('Age must be between 13 and 120', {
          invalidArgs: ['age']
        });
      }

      // Check if email already exists
      const existingUser = await context.db.users.findByEmail(input.email);
      if (existingUser) {
        throw new UserInputError('Email already in use', {
          invalidArgs: ['email']
        });
      }

      return await context.db.users.create(input);
    }
  }
};

// Using validation libraries
const Joi = require('joi');

const createUserSchema = Joi.object({
  name: Joi.string().min(2).max(50).required(),
  email: Joi.string().email().required(),
  age: Joi.number().integer().min(13).max(120).optional(),
  role: Joi.string().valid('USER', 'ADMIN', 'MODERATOR').required()
});

const resolvers = {
  Mutation: {
    createUser: async (parent, { input }, context) => {
      const { error, value } = createUserSchema.validate(input);

      if (error) {
        throw new UserInputError('Validation failed', {
          validationErrors: error.details
        });
      }

      return await context.db.users.create(value);
    }
  }
};
```

The **N+1 problem** occurs when a query results in multiple database calls - one for the initial data and N additional calls for related data.

```graphql
# This query can cause N+1 problem
query {
  posts {           # 1 query to get posts
    id
    title
    author {        # N queries (one per post) to get authors
      name
      email
    }
  }
}
```

**Problem Example:**
```javascript
// Naive resolver - causes N+1 problem
const resolvers = {
  Query: {
    posts: () => db.posts.findAll() // 1 query
  },
  Post: {
    author: (post) => db.users.findById(post.authorId) // N queries!
  }
};
```

**Solution 1: DataLoader (Batching)**
```javascript
const DataLoader = require('dataloader');

// Create batch function
const batchUsers = async (userIds) => {
  const users = await db.users.findByIds(userIds);
  return userIds.map(id => users.find(user => user.id === id));
};

// Create DataLoader instance
const userLoader = new DataLoader(batchUsers);

const resolvers = {
  Query: {
    posts: () => db.posts.findAll()
  },
  Post: {
    author: (post) => userLoader.load(post.authorId) // Batched!
  }
};

// Context setup
const server = new ApolloServer({
  typeDefs,
  resolvers,
  context: () => ({
    userLoader: new DataLoader(batchUsers)
  })
});
```

**Solution 2: Query Optimization**
```javascript
// Join data in single query
const resolvers = {
  Query: {
    posts: async () => {
      return await db.posts.findAll({
        include: [{ model: db.users, as: 'author' }]
      });
    }
  },
  Post: {
    author: (post) => post.author // Already loaded!
  }
};
```

**Authentication** verifies user identity, while **authorization** controls access to resources. GraphQL handles both through context and resolvers.

```javascript
// Authentication middleware
const jwt = require('jsonwebtoken');

const getUser = async (token) => {
  try {
    if (!token) return null;
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    return await db.users.findById(decoded.userId);
  } catch (error) {
    return null;
  }
};

// Server setup with authentication
const server = new ApolloServer({
  typeDefs,
  resolvers,
  context: async ({ req }) => {
    const token = req.headers.authorization?.replace('Bearer ', '');
    const user = await getUser(token);

    return {
      user,
      db,
      isAuthenticated: !!user,
      hasRole: (role) => user?.role === role
    };
  }
});
```

```graphql
# Schema with protected fields
type Query {
  posts: [Post!]!          # Public
  me: User                 # Requires authentication
  users: [User!]!          # Requires admin role
}

type Mutation {
  login(email: String!, password: String!): AuthPayload!
  createPost(input: CreatePostInput!): Post!  # Requires authentication
}

type AuthPayload {
  token: String!
  user: User!
}
```

```javascript
// Authorization in resolvers
const { AuthenticationError, ForbiddenError } = require('apollo-server');

const resolvers = {
  Query: {
    posts: () => db.posts.findAll(),

    me: (parent, args, { user }) => {
      if (!user) {
        throw new AuthenticationError('Authentication required');
      }
      return user;
    },

    users: (parent, args, { user }) => {
      if (!user) {
        throw new AuthenticationError('Authentication required');
      }
      if (user.role !== 'ADMIN') {
        throw new ForbiddenError('Admin access required');
      }
      return db.users.findAll();
    }
  },

  Mutation: {
    createPost: async (parent, { input }, { user }) => {
      if (!user) {
        throw new AuthenticationError('Authentication required');
      }

      return await db.posts.create({
        ...input,
        authorId: user.id
      });
    }
  }
};
```

GraphQL caching can be implemented at multiple levels: **query-level**, **field-level**, and **data-loader level**.

**1. HTTP Caching (Query-level)**
```javascript
const server = new ApolloServer({
  typeDefs,
  resolvers,
  plugins: [
    {
      requestDidStart() {
        return {
          willSendResponse(requestContext) {
            const { response, request } = requestContext;

            // Cache GET requests (queries)
            if (request.http.method === 'GET') {
              response.http.headers.set('Cache-Control', 'public, max-age=300');
            }
          }
        };
      }
    }
  ]
});
```

**2. In-Memory Caching with Redis**
```javascript
const Redis = require('redis');
const client = Redis.createClient();

const resolvers = {
  Query: {
    user: async (parent, { id }, context) => {
      const cacheKey = `user:${id}`;

      // Try cache first
      const cached = await client.get(cacheKey);
      if (cached) {
        return JSON.parse(cached);
      }

      // Fetch from database
      const user = await context.db.users.findById(id);

      // Cache for 5 minutes
      await client.setex(cacheKey, 300, JSON.stringify(user));

      return user;
    }
  }
};
```

