```javascript
const express = require('express');
const { graphqlHTTP } = require('express-graphql');
const { buildSchema } = require('graphql');

// 1. Define the Schema (SDL)
const schema = buildSchema(`
  type User {
    id: ID!
    name: String!
    email: String!
    posts: [Post!]!
  }

  type Post {
    id: ID!
    title: String!
    content: String!
    author: User!
  }

  type Query {
    hello: String
    user(id: ID!): User
    users: [User!]!
    post(id: ID!): Post
  }

  type Mutation {
    createUser(name: String!, email: String!): User!
    createPost(title: String!, content: String!, authorId: ID!): Post!
  }
`);

// 2. Mock Database
const mockUsers = {
  '1': { id: '1', name: 'Alice', email: 'alice@example.com' },
  '2': { id: '2', name: 'Bob', email: 'bob@example.com' },
};

const mockPosts = {
  '1': { id: '1', title: 'GraphQL Basics', content: 'Learning GraphQL...', authorId: '1' },
  '2': { id: '2', title: 'Advanced Queries', content: 'Complex queries...', authorId: '1' },
};

let nextUserId = 3;
let nextPostId = 3;

// 3. Create Resolvers
const root = {
  // Query resolvers
  hello: () => 'Hello, GraphQL World!',

  user: ({ id }) => {
    const user = mockUsers[id];
    if (!user) throw new Error(`User with id ${id} not found`);
    return user;
  },

  users: () => Object.values(mockUsers),

  post: ({ id }) => {
    const post = mockPosts[id];
    if (!post) throw new Error(`Post with id ${id} not found`);
    return {
      ...post,
      author: mockUsers[post.authorId]
    };
  },

  // Mutation resolvers
  createUser: ({ name, email }) => {
    const id = nextUserId.toString();
    nextUserId++;

    const newUser = { id, name, email };
    mockUsers[id] = newUser;
    return newUser;
  },

  createPost: ({ title, content, authorId }) => {
    if (!mockUsers[authorId]) {
      throw new Error(`Author with id ${authorId} not found`);
    }

    const id = nextPostId.toString();
    nextPostId++;

    const newPost = { id, title, content, authorId };
    mockPosts[id] = newPost;

    return {
      ...newPost,
      author: mockUsers[authorId]
    };
  }
};

// Add field resolvers for nested data
root.User = {
  posts: (parent) => {
    return Object.values(mockPosts)
      .filter(post => post.authorId === parent.id)
      .map(post => ({
        ...post,
        author: mockUsers[post.authorId]
      }));
  }
};

// 4. Set up Express Server
const app = express();

app.use('/graphql', graphqlHTTP({
  schema: schema,      // The schema defines API structure
  rootValue: root,     // The resolvers provide the data
  graphiql: true,      // Enable GraphiQL IDE for testing
}));

const PORT = 4000;
app.listen(PORT, () => {
  console.log(`🚀 GraphQL server running at http://localhost:${PORT}/graphql`);
  console.log(`📊 GraphiQL IDE available at http://localhost:${PORT}/graphql`);
});
```

