const jwt = require('jsonwebtoken');
const db = require('../database/connection');

const authMiddleware = async (req, res, next) => {
  try {
    const token = req.headers.authorization?.replace('Bearer ', '');

    if (!token) {
      req.user = null;
      return next();
    }

    // Verify JWT token
