    // Fetch user from database
    const users = await db.query(
      'SELECT id, name, email, role FROM users WHERE id = ?',
      [decoded.userId]
    );

    req.user = users[0] || null;
    next();
  } catch (error) {
    console.error('Auth error:', error);
    req.user = null;
    next();
  }
};

