**4. GraphQL Resolvers (schema/resolvers.js):**
```javascript
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const { AuthenticationError, ForbiddenError, UserInputError } = require('apollo-server-express');
const db = require('../database/connection');

const resolvers = {
  Query: {
    me: (parent, args, { user }) => {
      if (!user) throw new AuthenticationError('Not authenticated');
      return user;
    },

    users: async () => {
      return await db.query('SELECT * FROM users ORDER BY created_at DESC');
    },

    user: async (parent, { id }, { loaders }) => {
      return await loaders.userLoader.load(id);
    },

    posts: async (parent, { limit, offset }) => {
      return await db.query(
        'SELECT * FROM posts WHERE is_published = true ORDER BY created_at DESC LIMIT ? OFFSET ?',
        [limit, offset]
      );
    },

    post: async (parent, { id }, { loaders }) => {
      const post = await loaders.postLoader.load(id);
      if (!post) throw new UserInputError('Post not found');
      return post;
    }
  },

  Mutation: {
    register: async (parent, { input }) => {
      const { name, email, password } = input;

      // Check if user exists
      const existingUsers = await db.query(
        'SELECT id FROM users WHERE email = ?',
        [email]
      );

      if (existingUsers.length > 0) {
        throw new UserInputError('User with this email already exists');
      }

      // Hash password
      const hashedPassword = await bcrypt.hash(password, 12);

      // Create user
      const result = await db.query(
        'INSERT INTO users (name, email, password, role, created_at) VALUES (?, ?, ?, ?, NOW())',
        [name, email, hashedPassword, 'USER']
      );

      const user = {
        id: result.insertId,
        name,
        email,
        role: 'USER',
        createdAt: new Date().toISOString()
      };

      // Generate JWT token
      const token = jwt.sign(
        { userId: user.id },
        process.env.JWT_SECRET || 'your-secret-key',
        { expiresIn: '7d' }
      );

      return { token, user };
    },

    login: async (parent, { email, password }) => {
      const users = await db.query(
        'SELECT * FROM users WHERE email = ?',
        [email]
      );

      const user = users[0];
      if (!user) {
        throw new AuthenticationError('Invalid email or password');
      }

      const isValid = await bcrypt.compare(password, user.password);
      if (!isValid) {
        throw new AuthenticationError('Invalid email or password');
      }

      const token = jwt.sign(
        { userId: user.id },
        process.env.JWT_SECRET || 'your-secret-key',
        { expiresIn: '7d' }
      );

      return { token, user };
    },

    createPost: async (parent, { input }, { user, loaders }) => {
      if (!user) throw new AuthenticationError('Not authenticated');

      const { title, content, isPublished } = input;

      const result = await db.query(
        'INSERT INTO posts (title, content, author_id, is_published, created_at, updated_at) VALUES (?, ?, ?, ?, NOW(), NOW())',
        [title, content, user.id, isPublished]
      );

      const newPost = {
        id: result.insertId,
        title,
        content,
        author_id: user.id,
        isPublished,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      // Prime the cache
      loaders.postLoader.prime(newPost.id, newPost);

      return newPost;
    },

    updatePost: async (parent, { id, input }, { user }) => {
      if (!user) throw new AuthenticationError('Not authenticated');

      // Check ownership
      const posts = await db.query(
        'SELECT author_id FROM posts WHERE id = ?',
        [id]
      );

      const post = posts[0];
      if (!post) throw new UserInputError('Post not found');

      if (post.author_id !== user.id && user.role !== 'ADMIN') {
        throw new ForbiddenError('Not authorized to update this post');
      }

      // Build dynamic update query
      const updates = [];
      const values = [];

      Object.entries(input).forEach(([key, value]) => {
        if (value !== undefined) {
          updates.push(`${key.replace(/([A-Z])/g, '_$1').toLowerCase()} = ?`);
          values.push(value);
        }
      });

      if (updates.length === 0) {
        throw new UserInputError('No fields to update');
      }

      updates.push('updated_at = NOW()');
      values.push(id);

      await db.query(
        `UPDATE posts SET ${updates.join(', ')} WHERE id = ?`,
        values
      );

      // Return updated post
      const updatedPosts = await db.query(
        'SELECT * FROM posts WHERE id = ?',
        [id]
      );

      return updatedPosts[0];
    }
  },

  // Field resolvers
  User: {
    posts: (user, args, { loaders }) => {
      return loaders.postsByUserLoader.load(user.id);
    }
  },

  Post: {
    author: (post, args, { loaders }) => {
      return loaders.userLoader.load(post.author_id);
    },

    comments: (post, args, { loaders }) => {
      return loaders.commentsByPostLoader.load(post.id);
    }
  },

  Comment: {
    author: (comment, args, { loaders }) => {
      return loaders.userLoader.load(comment.author_id);
    },

    post: (comment, args, { loaders }) => {
      return loaders.postLoader.load(comment.post_id);
    }
  }
};

module.exports = resolvers;
```

**5. Main Server (server.js):**
```javascript
const express = require('express');
const { ApolloServer } = require('apollo-server-express');
const cors = require('cors');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
require('dotenv').config();

const typeDefs = require('./schema/typeDefs');
const resolvers = require('./schema/resolvers');
const authMiddleware = require('./middleware/auth');
const createLoaders = require('./loaders');
const db = require('./database/connection');

const startServer = async () => {
  const app = express();

  // Security and rate limiting
  app.use(helmet());
  app.use(cors());
  app.use(rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100 // limit each IP to 100 requests per windowMs
  }));

  // Auth middleware
  app.use(authMiddleware);

  // Create Apollo Server
  const server = new ApolloServer({
    typeDefs,
    resolvers,
    context: ({ req }) => ({
      user: req.user,
      loaders: createLoaders(db),
      db
    }),
    introspection: process.env.NODE_ENV !== 'production',
    playground: process.env.NODE_ENV !== 'production',
    formatError: (error) => {
      console.error(error);
      return {
        message: error.message,
        code: error.extensions?.code,
        path: error.path
      };
    }
  });

  await server.start();
  server.applyMiddleware({ app, path: '/graphql' });

  const PORT = process.env.PORT || 4000;

  app.listen(PORT, () => {
    console.log(`🚀 Server ready at http://localhost:${PORT}${server.graphqlPath}`);
  });

  // Graceful shutdown
  process.on('SIGTERM', async () => {
    console.log('SIGTERM received, shutting down gracefully');
    await server.stop();
    await db.close();
    process.exit(0);
  });
};

startServer().catch(error => {
  console.error('Error starting server:', error);
  process.exit(1);
});
```

